def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated tile interior color is the most common color.
    from collections import Counter
    base = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Grid lines contain little or none of the interior color.
    rlines = [r for r in range(h) if sum(v == base for v in grid[r]) <= w * 0.30]
    clines = [c for c in range(w) if sum(grid[r][c] == base for r in range(h)) <= h * 0.30]

    if len(rlines) < 2 or len(clines) < 2:
        return [[base]]

    nr, nc = len(rlines) - 1, len(clines) - 1
    canvas = [[base for _ in range(nc)] for _ in range(nr)]

    colors = set(v for row in grid for v in row) - {base}
    for color in colors:
        # Any fully outlined rectangle of marker intersections represents a filled region.
        for a in range(len(rlines) - 1):
            for b in range(a + 1, len(rlines)):
                for x in range(len(clines) - 1):
                    for y in range(x + 1, len(clines)):
                        top, bottom = rlines[a], rlines[b]
                        left, right = clines[x], clines[y]
                        if (all(grid[top][c] == color for c in clines[x:y + 1]) and
                            all(grid[bottom][c] == color for c in clines[x:y + 1]) and
                            all(grid[r][left] == color for r in rlines[a:b + 1]) and
                            all(grid[r][right] == color for r in rlines[a:b + 1])):
                            for rr in range(a, b):
                                for cc in range(x, y):
                                    canvas[rr][cc] = color

    occupied = [(r, c) for r in range(nr) for c in range(nc)
                if canvas[r][c] != base]
    if not occupied:
        return [[base]]
    r0 = min(r for r, _ in occupied)
    r1 = max(r for r, _ in occupied)
    c0 = min(c for _, c in occupied)
    c1 = max(c for _, c in occupied)
    return [row[c0:c1 + 1] for row in canvas[r0:r1 + 1]]
